/*
 * /chimpanzee PULSE — an offline-first music experience.
 * Native Android wrapper: Capacitor. No external runtime JS dependencies.
 * Files stay on-device in IndexedDB; never uploaded to a server.
 */
'use strict';
const $=selector=>document.querySelector(selector);
const $$=selector=>Array.from(document.querySelectorAll(selector));
const icon=name=>`<svg aria-hidden="true"><use href="#i-${name}"></use></svg>`;
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=seconds=>{if(!Number.isFinite(Number(seconds)))return'0:00';const n=Math.max(0,Math.floor(Number(seconds)));return`${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`};
const prettyBytes=n=>n>1024**3?(n/1024**3).toFixed(1)+' GB':n>1024**2?(n/1024**2).toFixed(1)+' MB':n>1024?(n/1024).toFixed(1)+' KB':'0 B';
const uid=()=>globalThis.crypto?.randomUUID?.()||'t'+Date.now()+Math.random().toString(36).slice(2);
const getJSON=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const saved=getJSON('pulse.settings.v1',{});
const tabs=[['home','home','Home'],['library','library','Library'],['playlists','playlists','Playlists'],['queue','queue','Queue'],['rooms','radio','Live Rooms']];
const state={page:'home',filter:'all',sort:'recent',query:'',tracks:new Map(),playlists:saved.playlists||{},playlist:null,queue:saved.queue||[],current:saved.current||null,playing:false,shuffle:!!saved.shuffle,repeat:saved.repeat||'all',volume:saved.volume??.85,rate:saved.rate??1,theme:saved.theme||'dark',listenSeconds:Number(saved.listenSeconds)||0,roomServer:saved.roomServer||'',profile:saved.profile||'Listener',sleepUntil:0,db:null,importing:false,playerToken:0,room:null,connection:null,roomId:null,role:null,adminRequest:null};
const audio=$('#audio');audio.volume=state.volume;audio.playbackRate=state.rate;
let objectURL=null,audioContext=null,analyser=null,frequencyData=null,lastListenMark=Date.now(),visualFrame=0,visualTicks=0,sleepTimer=null;
const navLabel=p=>({home:'YOUR FREQUENCY',library:'YOUR LIBRARY',playlists:'YOUR COLLECTIONS',queue:'UP NEXT',rooms:'LIVE CONNECTIONS',settings:'PREFERENCES'})[p]||'YOUR FREQUENCY';
const track=id=>state.tracks.get(id);
const allTracks=()=>[...state.tracks.values()];
const setBodyTheme=()=>{document.body.classList.toggle('theme-light',state.theme==='light');document.body.classList.toggle('theme-dark',state.theme!=='light');$('meta[name="theme-color"]')?.setAttribute('content',state.theme==='light'?'#f4f1f0':'#0c0c11')};
function saveSettings(){try{localStorage.setItem('pulse.settings.v1',JSON.stringify({playlists:state.playlists,queue:state.queue,current:state.current,shuffle:state.shuffle,repeat:state.repeat,volume:state.volume,rate:state.rate,theme:state.theme,listenSeconds:state.listenSeconds,roomServer:state.roomServer,profile:state.profile}))}catch(e){console.warn('Could not save preferences',e)}}
function toast(text,type='ok'){const el=document.createElement('div');el.className='toast';el.innerHTML=`${icon(type==='error'?'close':'check-circle')}<span>${escapeHTML(text)}</span>`;$('#toast-root').append(el);setTimeout(()=>{el.classList.add('hide');setTimeout(()=>el.remove(),350)},3400)}
function nav(){const desktop=tabs.concat([['settings','settings','Settings']]);$('#desktop-nav').innerHTML=desktop.map(([page,glyph,title])=>`<button class="nav-item ${state.page===page?'active':''}" data-action="navigate" data-page="${page}" ${state.page===page?'aria-current="page"':''}>${icon(glyph)}<span>${title}</span>${page==='library'?`<span class="nav-badge">${state.tracks.size}</span>`:''}</button>`).join('');$('#mobile-nav').innerHTML=tabs.map(([page,glyph,title])=>`<button data-action="navigate" data-page="${page}" class="${state.page===page?'active':''}" ${state.page===page?'aria-current="page"':''}>${icon(glyph)}<span>${title==='Live Rooms'?'Rooms':title}</span></button>`).join('');$('#page-eyebrow').textContent=navLabel(state.page)}
function route(page){if(!tabs.some(t=>t[0]===page)&&page!=='settings')page='home';state.page=page;state.query=page==='library'?state.query:'';render();window.scrollTo({top:0,behavior:'instant'})}
function render(){setBodyTheme();nav();$('#screen').innerHTML=({home:renderHome,library:renderLibrary,playlists:renderPlaylists,queue:renderQueue,rooms:renderRooms,settings:renderSettings}[state.page]||renderHome)();renderPlayer();bindHero();if(state.page==='rooms'){const e=$('.room-chat');if(e)e.scrollTop=e.scrollHeight}}
function heading(kicker,title,copy,extra=''){return`<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1 class="page-title">${title}</h1><p class="subcopy">${copy}</p></div>${extra}</div>`}
function prettyCount(n,word){return`${n} ${word}${n===1?'':'s'}`}
function empty(title,desc,action='import',label='Import music'){return`<div class="empty-state"><div class="empty-orb">${icon('disc')}</div><h2>${escapeHTML(title)}</h2><p>${escapeHTML(desc)}</p><button class="primary-btn" data-action="${action}">${icon('plus')}${escapeHTML(label)}</button></div>`}
function coverHue(t){let h=9;for(const c of(t.title+t.artist))h=(h*31+c.charCodeAt(0))%360;return h}
function cover(t,extra=''){return`<div class="cover ${extra}" style="--cover-hue:${coverHue(t)}"><span class="cover-shine"></span></div>`}
function trackRow(t,i=0,opts={}){const current=state.current===t.id,active=current&&state.playing;return`<div class="track-row ${current?'is-active':''}" style="animation-delay:${Math.min(i*22,230)}ms">
 ${opts.number!==false?`<div class="track-index">${active?`<span class="equalizer-mini"><b></b><b></b><b></b></span>`:i+1}</div>`:''}
 <button class="track-main-action" data-action="play-track" data-id="${t.id}" title="Play ${escapeHTML(t.title)}">${cover(t)}<span class="track-text"><span class="track-title" style="display:block">${escapeHTML(t.title)}</span><span class="track-artist" style="display:block">${escapeHTML(t.artist)}</span></span></button>
 <span class="track-meta">${fmt(t.duration)}</span>
 <button class="track-btn ${t.favorite?'loved':''}" data-action="favorite" data-id="${t.id}" aria-label="${t.favorite?'Remove favorite':'Add favorite'}" title="Favorite">${icon('heart')}</button>
 ${opts.queue?`<button class="track-btn" data-action="queue-up" data-id="${t.id}" aria-label="Move up" title="Move up">${icon('up')}</button><button class="track-btn" data-action="queue-down" data-id="${t.id}" aria-label="Move down" title="Move down">${icon('down')}</button><button class="track-btn" data-action="queue-remove" data-id="${t.id}" aria-label="Remove from queue">${icon('close')}</button>`:opts.playlist?`<button class="track-btn" data-action="playlist-remove" data-id="${t.id}" title="Remove from playlist">${icon('close')}</button>`:`<button class="track-btn" data-action="track-menu" data-id="${t.id}" title="Track options" aria-label="Track options">${icon('more')}</button>`}
 </div>`}
function sectionTitle(title,caption,right=''){return`<div class="section-header"><div><h2 class="section-title">${title}</h2>${caption?`<p class="section-subtitle">${caption}</p>`:''}</div>${right}</div>`}
function renderHome(){const entries=allTracks();const recent=entries.slice().sort((a,b)=>(b.lastPlayed||b.added)-(a.lastPlayed||a.added)).slice(0,5);const favs=entries.filter(t=>t.favorite).length;
 return`<section class="hero ${state.playing?'playing':''}"><div class="hero-copy"><div class="hero-chip"><span class="live-dot"></span> THE SOUND IS YOURS</div><h1 class="hero-title">Feel<br><em>everything.</em></h1><p class="hero-description">A home for every track you love. Unfiltered sound. Beautiful motion. No interruptions.</p><div class="hero-actions"><button class="primary-btn" data-action="${entries.length?'resume':'import'}">${icon(entries.length?'play':'plus')}${entries.length?'Play my music':'Add your music'}</button><button class="glass-btn" data-action="navigate" data-page="library">${icon('library')} Explore library</button></div></div><div class="hero-art" aria-hidden="true"><div class="art-orbit"></div><canvas id="hero-canvas" class="hero-canvas"></canvas><div class="hero-disc"></div><div class="hero-float">${icon('spark')} Hi-Fidelity Vibes</div><span class="orbit-label">CHIMPANZEE / 02</span></div></section>
 <div class="stats-strip"><div class="stat-card"><span class="stat-icon">${icon('disc')}</span><div><div class="stat-value">${entries.length}</div><div class="stat-label">Tracks saved</div></div><span class="stat-action">↗</span></div><div class="stat-card"><span class="stat-icon">${icon('heart')}</span><div><div class="stat-value">${favs}</div><div class="stat-label">Favorites</div></div><span class="stat-action">↗</span></div><div class="stat-card"><span class="stat-icon">${icon('headphones')}</span><div><div class="stat-value">${Math.floor(state.listenSeconds/60)}<span style="font-size:12px;color:var(--muted)">m</span></div><div class="stat-label">Time listened</div></div><span class="stat-action">↗</span></div></div>
 <div class="content-grid"><section>${sectionTitle('Your rotation','The music closest to you',`<button class="section-action" data-action="navigate" data-page="library">View library ${icon('chevron')}</button>`)}<div class="surface-card">${recent.length?`<div class="track-list">${recent.map((t,i)=>trackRow(t,i,{number:false})).join('')}</div>`:`<div class="empty-inline">${icon('disc')}Your collection starts with a song.<br>Import audio files to see your rotation here.<button class="secondary-btn" data-action="import">${icon('plus')} Add songs</button></div>`}</div></section><section>${sectionTitle('Made for you','Small touches. Big energy.')}<div class="surface-card"><div class="surface-header"><strong>Quick moves</strong>${icon('spark')}</div><button class="quick-action" data-action="import"><span class="icon-circle">${icon('upload')}</span><span><strong>Drop something new</strong><small>Your files, stored privately</small></span>${icon('chevron')}</button><button class="quick-action" data-action="navigate" data-page="playlists"><span class="icon-circle">${icon('playlists')}</span><span><strong>Curate a playlist</strong><small>Build your next favorite mix</small></span>${icon('chevron')}</button><button class="quick-action" data-action="navigate" data-page="rooms"><span class="icon-circle">${icon('radio')}</span><span><strong>Find your people</strong><small>Station chat and shared queues</small></span>${icon('chevron')}</button></div></section></div>`}
function sortedTracks(){let arr=allTracks();if(state.filter==='favorites')arr=arr.filter(t=>t.favorite);if(state.filter==='recent')arr=arr.filter(t=>t.lastPlayed);if(state.query)arr=arr.filter(t=>(t.title+' '+t.artist).toLowerCase().includes(state.query.toLowerCase()));const {sort}=state;arr.sort(sort==='az'?(a,b)=>a.title.localeCompare(b.title):sort==='played'?(a,b)=>(b.plays||0)-(a.plays||0):sort==='duration'?(a,b)=>b.duration-a.duration:(a,b)=>(b.added||0)-(a.added||0));return arr}
function renderLibrary(){const rows=sortedTracks();return`${heading('PERSONAL ARCHIVE','Your library.','Every track belongs here. Your music is stored on this device—offline and completely yours.',`<span class="count-pill">${prettyCount(state.tracks.size,'track')} · ${prettyBytes(allTracks().reduce((n,t)=>n+(t.size||0),0))}</span>`)}
 <div class="chip-row">${[['all','All tracks'],['favorites','Favorites'],['recent','Recently played']].map(([key,label])=>`<button class="chip ${state.filter===key?'active':''}" data-action="filter" data-filter="${key}">${label}</button>`).join('')}</div>
 <div class="library-tools"><div class="field-wrap">${icon('search')}<input id="library-search" class="field" placeholder="Find a track or artist…" value="${escapeHTML(state.query)}" autocomplete="off"></div><select id="library-sort" class="select-field" aria-label="Sort tracks"><option value="recent" ${state.sort==='recent'?'selected':''}>Recently added</option><option value="az" ${state.sort==='az'?'selected':''}>Title A – Z</option><option value="played" ${state.sort==='played'?'selected':''}>Most played</option><option value="duration" ${state.sort==='duration'?'selected':''}>Longest first</option></select></div>
 ${!state.tracks.size?empty('Your sound starts here.','Import music files from your device. They stay in your own private offline library.'):!rows.length?`<div class="empty-state"><div class="empty-orb">${icon('search')}</div><h2>Nothing on this frequency.</h2><p>Try a different search or filter.</p><button class="secondary-btn" data-action="clear-filter">Clear filters</button></div>`:`<div class="library-list"><div class="list-header"><span>SONG / ARTIST</span><span>TIME</span></div><div class="track-list">${rows.map((t,i)=>trackRow(t,i)).join('')}</div></div>`}
 <button class="drop-zone" id="drop-zone" data-action="import">${icon('upload')} Drop audio files here, or tap to browse your device</button>`}
function renderPlaylists(){const names=Object.keys(state.playlists);if(state.playlist&&!state.playlists[state.playlist])state.playlist=null;
 if(state.playlist){const title=state.playlist,ids=state.playlists[title]||[],entries=ids.map(track).filter(Boolean);return`${heading('HANDCRAFTED COLLECTION','${escapeHTML(title)}',`${prettyCount(entries.length,'track')} in this playlist`)}<div class="playlist-toolbar"><button class="secondary-btn" data-action="playlist-back">${icon('back')} All playlists</button><button class="primary-btn" data-action="playlist-play" ${entries.length?'':'disabled'}>${icon('play')} Play collection</button><button class="secondary-btn danger" data-action="playlist-delete">${icon('trash')} Delete</button></div>${entries.length?`<div class="library-list">${entries.map((t,i)=>trackRow(t,i,{playlist:true})).join('')}</div>`:empty('An empty canvas.','Find a song in your library, open its options and add it to this playlist.','navigate-library','Open library')}`}
 return`${heading('THE WAY YOU HEAR IT','Your playlists.','Collect the tracks that fit the moment. Create your own world, one song at a time.',`<span class="count-pill">${prettyCount(names.length,'playlist')}</span>`)}<div class="playlist-grid"><button class="playlist-tile playlist-create" data-action="playlist-new">${icon('plus')}<strong>Create playlist</strong><span class="small-note">Give a mood a name</span></button>${names.map((name,i)=>`<button class="playlist-tile" data-action="playlist-open" data-name="${escapeHTML(name)}" style="animation:enter .4s ${i*50}ms both"><div class="playlist-cover">${icon('disc')}</div><div class="playlist-name">${escapeHTML(name)}</div><div class="playlist-caption">${prettyCount((state.playlists[name]||[]).length,'track')}</div></button>`).join('')}</div>`}
function renderQueue(){const tracks=state.queue.map(track).filter(Boolean);return`${heading('WHAT COMES NEXT','The queue.','Build your listening journey. Reorder tracks, bring favorites forward, and let the music flow.',`<span class="count-pill">${prettyCount(tracks.length,'track')}</span>`)}
 <div class="playlist-toolbar"><button class="primary-btn" data-action="queue-play" ${tracks.length?'':'disabled'}>${icon('play')} Play queue</button><button class="secondary-btn" data-action="navigate" data-page="library">${icon('plus')} Browse tracks</button><button class="secondary-btn" data-action="queue-clear" ${tracks.length?'':'disabled'}>${icon('trash')} Clear queue</button></div>${tracks.length?`<div class="surface-card"><div class="surface-header"><strong>Playing order</strong><span class="small-note">${fmt(tracks.reduce((sum,t)=>sum+(t.duration||0),0))} total</span></div>${tracks.map((t,i)=>trackRow(t,i,{queue:true})).join('')}</div>`:empty('Your queue is wide open.','Add tracks from your library to create a listening session.','navigate-library','Browse your library')}`}
function renderRooms(){const r=state.room;let body;
 if(!r){body=`<div class="room-layout"><div class="room-panel"><h3>Start a station</h3><p>Become the host. Invite friends with a short PIN and manage a shared station queue.</p><div class="form-group"><label for="host-name">YOUR NAME</label><input class="field" id="host-name" maxlength="30" value="${escapeHTML(state.profile)}"></div><button class="primary-btn" data-action="room-create">${icon('radio')} Create station</button></div><div class="room-panel"><h3>Join the frequency</h3><p>Already have a PIN? Jump into a friend's room for group chat and queue updates.</p><div class="form-group"><label for="join-pin">STATION PIN</label><input class="field" id="join-pin" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" placeholder="0000"></div><div class="form-group"><label for="join-name">YOUR NAME</label><input class="field" id="join-name" maxlength="30" value="${escapeHTML(state.profile)}"></div><button class="secondary-btn" data-action="room-join">${icon('chevron')} Join station</button></div></div>`}else{const isHost=state.role==='host';const canManage=isHost||state.role==='admin';body=`<div class="room-layout"><div class="room-panel"><span class="room-connection">CONNECTED</span><h3 style="margin-top:15px">Station ${escapeHTML(r.pin)}</h3><p>Your 4-digit PIN rotates automatically. Share the current PIN with people you trust.</p><div class="pin-display">${escapeHTML(r.pin)}</div><button class="secondary-btn" data-action="copy-pin">${icon('link')} Copy PIN</button><button class="secondary-btn danger" data-action="room-leave">${icon('log-out')} ${isHost?'End station':'Leave'}</button><h3 style="margin-top:27px">Listeners <span class="small-note">(${r.members.length})</span></h3>${r.members.map(m=>`<div class="room-member"><span class="member-avatar">${escapeHTML(m.name.slice(0,1).toUpperCase())}</span><div style="flex:1;min-width:0"><strong>${escapeHTML(m.name)}</strong><small>${escapeHTML(m.role)}</small></div>${isHost&&m.role!=='host'?`<button class="track-btn" data-action="room-admin" data-id="${m.id}" data-grant="${m.role!=='admin'}" title="${m.role==='admin'?'Revoke admin':'Grant admin'}">${icon(m.role==='admin'?'close':'plus')}</button>`:''}</div>`).join('')}${state.role==='listener'?`<button class="secondary-btn" style="margin-top:16px" data-action="request-admin">${icon('spark')} Request admin</button>`:''}${state.adminRequest&&isHost?`<div class="message-callout">${escapeHTML(state.adminRequest.name)} requested admin access.<button class="secondary-btn" data-action="grant-request" style="margin-top:8px">Grant access</button></div>`:''}</div>
 <div class="room-panel"><h3>Station chat</h3><p>Messages appear live for everyone in the room.</p><div class="room-chat">${r.chat.length?r.chat.map(m=>`<div class="chat-bubble ${m.from===state.roomId?'self':''}"><strong>${escapeHTML(m.name)}</strong>${escapeHTML(m.text)}</div>`).join(''):`<div class="empty-inline">Say hello. This room is yours.</div>`}</div><div class="chat-compose"><input id="chat-message" class="field" maxlength="500" placeholder="Say something…"><button class="primary-btn" data-action="room-chat">${icon('send')}</button></div><div class="message-callout"><strong>Shared queue</strong><br>Hosts and admins can add approved YouTube or Google Drive links for everyone to see. Audio is not rebroadcast or synchronized.</div>${canManage?`<div class="form-group"><input class="field" id="room-link" placeholder="Paste YouTube or Drive link"><input class="field" id="room-link-title" placeholder="Track title"></div><button class="secondary-btn" data-action="room-track-add">${icon('plus')} Add to station queue</button>`:''}<div class="track-list">${r.queue.map((t,i)=>`<div class="track-row"><span class="track-index">${i+1}</span><span class="track-text"><span class="track-title" style="display:block">${escapeHTML(t.title)}</span><span class="track-artist" style="display:block">${escapeHTML(t.source)}</span></span><button class="track-btn" data-action="room-link-open" data-url="${escapeHTML(t.url)}" title="Open authorized source">${icon('link')}</button>${canManage?`<button class="track-btn" data-action="room-track-remove" data-id="${t.id}">${icon('close')}</button>`:''}</div>`).join('')}</div></div></div>`}
 return`${heading('FIND YOUR PEOPLE','Stay in sync.','One room, one conversation. Real-time station chat and shared queues—no pretending that unsupported audio is synchronized.')}<div class="room-hero"><div><div class="eyebrow">LIVE / TOGETHER</div><h2>Good music<br>travels together.</h2><p>Connect through a room PIN and build a shared queue.</p></div><div class="room-orb">${icon('radio')}</div></div>${!state.roomServer?`<div class="message-callout"><strong>Connect your live server first.</strong> Rooms need a deployed WebSocket server. <button class="section-action" style="display:inline-flex" data-action="navigate" data-page="settings">Configure in Settings →</button></div>`:''}${body}`}
function renderSettings(){const entries=allTracks(),total=entries.reduce((n,t)=>n+(t.size||0),0);return`${heading('MAKE IT YOURS','The details.','A little more control, a lot more you. Your music never leaves your device.')}<div class="settings-grid"><div><div class="utility-card"><h3>Your experience</h3><div class="setting-line"><div><strong>Light appearance</strong><span>Switch between midnight and soft paper.</span></div><button class="toggle ${state.theme==='light'?'on':''}" data-action="toggle-theme" role="switch" aria-checked="${state.theme==='light'}" aria-label="Light appearance"></button></div><div class="setting-line"><div><strong>Shuffle</strong><span>Surprise me with a new song.</span></div><button class="toggle ${state.shuffle?'on':''}" data-action="shuffle" role="switch" aria-checked="${state.shuffle}" aria-label="Shuffle"></button></div><div class="setting-line"><div><strong>Repeat</strong><span>Current mode: ${escapeHTML(state.repeat)}.</span></div><button class="secondary-btn" data-action="repeat">${icon('repeat')} Change mode</button></div><div class="setting-line"><div><strong>Playback speed</strong><span>Set the pace of your music.</span></div><select class="select-field" id="playback-rate"><option value="0.75" ${state.rate===.75?'selected':''}>0.75×</option><option value="1" ${state.rate===1?'selected':''}>1× normal</option><option value="1.25" ${state.rate===1.25?'selected':''}>1.25×</option><option value="1.5" ${state.rate===1.5?'selected':''}>1.5×</option><option value="2" ${state.rate===2?'selected':''}>2×</option></select></div><div class="setting-line"><div><strong>Sleep timer</strong><span>${state.sleepUntil?'Music will pause when your timer ends.':'Set a gentle stop for your music.'}</span></div><button class="secondary-btn" data-action="sleep-modal">${icon('clock')} ${state.sleepUntil?'Change':'Set timer'}</button></div></div>
 <div class="utility-card"><h3>Live stations</h3><p>Rooms require a separately hosted secure WebSocket server. The station backend is not bundled into this app.</p><div class="form-group"><label for="server-url">SERVER ADDRESS (HTTPS / WSS)</label><input class="field" id="server-url" value="${escapeHTML(state.roomServer)}" placeholder="https://your-server.example.com" inputmode="url"></div><div class="form-group"><label for="profile-name">YOUR DISPLAY NAME</label><input class="field" id="profile-name" maxlength="30" value="${escapeHTML(state.profile)}" placeholder="Listener"></div><button class="secondary-btn" data-action="save-server">${icon('check')} Save settings</button></div></div>
 <div><div class="utility-card"><h3>On-device storage</h3><div class="stat-value" style="font-size:36px;margin:16px 0 0">${prettyBytes(total)}</div><p>${prettyCount(entries.length,'audio file')} saved privately on this device. Stored in your browser or Android app storage—not cloud synced.</p><div class="message-callout">If you clear app data or uninstall, downloaded music can be lost. Keep the original audio files safely backed up.</div><div class="small-buttons" style="margin-top:16px"><button data-action="storage-persist">Protect storage</button><button data-action="export-data">Export playlist list</button></div></div>
 <div class="utility-card"><h3>Fresh start</h3><p>Remove all songs, playlists and listening history stored inside this app.</p><button class="secondary-btn danger" style="margin-top:15px" data-action="delete-all">${icon('trash')} Clear local library</button></div><div class="utility-card"><div class="eyebrow">BUILT FOR THE FEELING</div><h3 style="font-size:25px;margin:12px 0 6px">/chimpanzee PULSE</h3><p>Edition 02 · Offline-first player · Material you own</p><p style="margin-top:9px">Real-world playback and storage, immersive motion, and optional station chat. Not a licensed streaming catalog or an audio rebroadcasting service.</p></div></div></div>`}
function renderPlayer(){const t=track(state.current);const playing=state.playing;const hasTracks=state.tracks.size>0;const controls=`<div class="player-main-controls"><div class="transport"><button data-action="shuffle" class="${state.shuffle?'is-on':''}" title="Shuffle" aria-label="Shuffle">${icon('shuffle')}</button><button data-action="previous" title="Previous track" aria-label="Previous">${icon('prev')}</button><button class="transport-play" data-action="toggle-play" title="${playing?'Pause':'Play'}" aria-label="${playing?'Pause':'Play'}">${icon(playing?'pause':'play')}</button><button data-action="next" title="Next track" aria-label="Next">${icon('next')}</button><button data-action="repeat" class="${state.repeat!=='off'?'is-on':''}" title="Repeat: ${state.repeat}" aria-label="Repeat">${icon('repeat')}</button></div><div class="seek-group"><span id="current-time">${fmt(audio.currentTime)}</span><input id="seek" class="range" type="range" min="0" max="${Math.max(0,audio.duration||t?.duration||0)}" value="${audio.currentTime||0}" step="0.1" style="--fill:0%" aria-label="Seek position"><span id="total-time">${fmt(audio.duration||t?.duration||0)}</span></div></div>`;
 $('#player-inner').innerHTML=`<div class="now-track">${t?cover(t,'small-cover'):`<div class="cover small-cover" style="--cover-hue:10">${icon('disc')}</div>`}<div class="now-info"><div class="now-name">${escapeHTML(t?.title||'Your sound awaits')}</div><div class="now-artist ${t?'':'empty'}">${escapeHTML(t?.artist||'Add music to begin your journey')}</div></div>${t?`<button data-action="favorite" data-id="${t.id}" class="track-btn ${t.favorite?'loved':''}" title="Favorite">${icon('heart')}</button>`:''}</div>${controls}<div class="now-options"><button data-action="mute" title="Mute">${icon(state.volume===0?'mute':'volume')}</button><input id="volume" class="range" type="range" min="0" max="1" step="0.01" value="${state.volume}" style="--fill:${state.volume*100}%" aria-label="Volume"><button data-action="navigate" data-page="queue" title="Queue">${icon('queue')}</button></div><div class="mobile-transport" style="display:none"><button data-action="next" title="Skip">${icon('next')}</button><button data-action="toggle-play" class="mobile-play" aria-label="${playing?'Pause':'Play'}">${icon(playing?'pause':'play')}</button></div>`;
 if(window.innerWidth<=800){const mobile=$('.mobile-transport');if(mobile)mobile.style.display='flex'}updateProgress();document.body.classList.toggle('playing',state.playing)}
function updateProgress(){const max=Number.isFinite(audio.duration)?audio.duration:(track(state.current)?.duration||0),now=audio.currentTime||0,ratio=max>0?Math.min(100,now/max*100):0;const seek=$('#seek');if(seek&&!seek.matches(':active')){seek.max=Math.max(0,max);seek.value=now;seek.style.setProperty('--fill',ratio+'%')}const c=$('#current-time');if(c)c.textContent=fmt(now);const total=$('#total-time');if(total)total.textContent=fmt(max);$('#player-progress-fill').style.width=ratio+'%'}
/* Storage */
function openDB(){return new Promise((resolve,reject)=>{const request=indexedDB.open('chimpanzee-pulse-library',1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains('tracks'))request.result.createObjectStore('tracks',{keyPath:'id'})};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
function dbAll(){return new Promise((resolve,reject)=>{const req=state.db.transaction('tracks').objectStore('tracks').getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
function dbGet(id){return new Promise((resolve,reject)=>{const req=state.db.transaction('tracks').objectStore('tracks').get(id);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
function dbPut(record){return new Promise((resolve,reject)=>{const tx=state.db.transaction('tracks','readwrite');tx.objectStore('tracks').put(record);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
function dbDelete(id){return new Promise((resolve,reject)=>{const tx=state.db.transaction('tracks','readwrite');tx.objectStore('tracks').delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
function dbClear(){return new Promise((resolve,reject)=>{const tx=state.db.transaction('tracks','readwrite');tx.objectStore('tracks').clear();tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
function publicMeta(record){const {file,...meta}=record;return meta}
async function patchTrack(id,values){const rec=await dbGet(id);if(!rec)return;Object.assign(rec,values);await dbPut(rec);state.tracks.set(id,publicMeta(rec));saveSettings();render()}
function filenameMeta(filename){const noext=filename.replace(/\.[^/.]+$/,'').replace(/[_]+/g,' ').trim();const split=noext.split(/\s+[-–—]\s+/);return {title:(split.length>=2?split.slice(1).join(' - '):noext)||'Untitled audio',artist:split.length>=2?split[0]:'Unknown artist'}}
function getDuration(file){return new Promise(resolve=>{const temp=document.createElement('audio'),url=URL.createObjectURL(file);let finished=false;const finish=duration=>{if(finished)return;finished=true;temp.removeAttribute('src');temp.load();URL.revokeObjectURL(url);clearTimeout(timer);resolve(Number.isFinite(duration)?duration:0)};const timer=setTimeout(()=>finish(0),4500);temp.preload='metadata';temp.onloadedmetadata=()=>finish(temp.duration);temp.onerror=()=>finish(0);temp.src=url})}
async function importFiles(fileList){const files=Array.from(fileList||[]).filter(f=>f.type.startsWith('audio/')||/\.(mp3|m4a|aac|wav|ogg|flac|opus|webm)$/i.test(f.name));if(!files.length){toast('Choose supported audio files','error');return}if(!state.db){toast('Device storage is not available','error');return}let added=0,errors=0;state.importing=true;toast(`Importing ${prettyCount(files.length,'track')}…`);for(const file of files){try{const data=filenameMeta(file.name),duration=await getDuration(file),id=uid();const record={id,...data,duration,size:file.size,added:Date.now(),lastPlayed:0,plays:0,favorite:false,file};await dbPut(record);state.tracks.set(id,publicMeta(record));if(!state.queue.includes(id))state.queue.push(id);added++}catch(e){console.error('Import error',e);errors++}}state.importing=false;saveSettings();render();if(added)toast(`${prettyCount(added,'track')} added to your library`);if(errors)toast(`${errors} file(s) could not be saved. Check available storage.`,'error');if(!state.current&&state.queue.length)await loadTrack(state.queue[0],false)}
async function deleteTrack(id){if(!state.tracks.has(id))return;await dbDelete(id);state.tracks.delete(id);state.queue=state.queue.filter(t=>t!==id);for(const name in state.playlists)state.playlists[name]=state.playlists[name].filter(x=>x!==id);if(state.current===id){audio.pause();audio.removeAttribute('src');audio.load();if(objectURL)URL.revokeObjectURL(objectURL);objectURL=null;state.current=null;state.playing=false;if(state.queue.length)await loadTrack(state.queue[0],false)}saveSettings();render();toast('Removed from this device')}
/* Audio */
function activateVisualizer(){try{if(!audioContext){const AudioClass=window.AudioContext||window.webkitAudioContext;if(!AudioClass)return;audioContext=new AudioClass();analyser=audioContext.createAnalyser();analyser.fftSize=256;analyser.smoothingTimeConstant=.75;frequencyData=new Uint8Array(analyser.frequencyBinCount);const source=audioContext.createMediaElementSource(audio);source.connect(analyser);analyser.connect(audioContext.destination)}if(audioContext.state==='suspended')audioContext.resume().catch(()=>{})}catch(e){console.warn('Visualizer unavailable',e)}}
async function loadTrack(id,autoplay=true){if(!state.tracks.has(id)){toast('Track unavailable','error');return}const token=++state.playerToken;audio.pause();state.playing=false;audio.removeAttribute('src');audio.load();if(objectURL){URL.revokeObjectURL(objectURL);objectURL=null}try{const rec=await dbGet(id);if(token!==state.playerToken)return;if(!rec?.file){toast('The audio file was not found','error');return}objectURL=URL.createObjectURL(rec.file);audio.src=objectURL;audio.load();audio.playbackRate=state.rate;audio.volume=state.volume;state.current=id;const plays=(rec.plays||0)+(autoplay?1:0),lastPlayed=autoplay?Date.now():rec.lastPlayed;state.tracks.set(id,{...publicMeta(rec),plays,lastPlayed});if(autoplay)dbPut({...rec,plays,lastPlayed}).catch(console.warn);saveSettings();render();if(autoplay){activateVisualizer();await audio.play().catch(e=>{console.warn('Playback blocked',e);toast('Tap play to start audio','error')})}updateMediaSession()}catch(e){console.error(e);toast('Could not load the audio file','error')}}
function getQueueIndex(){return state.queue.indexOf(state.current)}
async function playTrack(id){if(!state.tracks.has(id))return;if(!state.queue.includes(id)){const idx=getQueueIndex();state.queue.splice(Math.max(0,idx+1),0,id)}await loadTrack(id,true)}
async function togglePlay(){if(!state.current){const id=state.queue.find(track)||allTracks()[0]?.id;if(!id){toast('Add a song to start listening');$('#file-input').click();return}await loadTrack(id,true);return}if(audio.paused){activateVisualizer();await audio.play().catch(()=>toast('Playback could not start','error'))}else audio.pause()}
async function nextTrack(isEnded=false){let list=state.queue.filter(track);if(!list.length)list=allTracks().map(t=>t.id);if(!list.length)return;if(isEnded&&state.repeat==='one'){audio.currentTime=0;await audio.play().catch(()=>{});return}const i=list.indexOf(state.current);let next;if(state.shuffle&&list.length>1){const other=list.filter(id=>id!==state.current);next=other[Math.floor(Math.random()*other.length)]}else next=list[i+1]||((state.repeat==='all'||!isEnded)?list[0]:null);if(!next){audio.pause();state.playing=false;renderPlayer();return}await loadTrack(next,true)}
async function previousTrack(){if(audio.currentTime>3){audio.currentTime=0;return}const list=state.queue.filter(track),i=list.indexOf(state.current),prev=list[Math.max(i-1,0)]||list[0];if(prev)await loadTrack(prev,true)}
function onPlayState(playing){state.playing=playing;renderPlayer();if(state.page==='home'){$('.hero')?.classList.toggle('playing',playing)}if(state.page==='library'||state.page==='queue'||state.page==='playlists'){document.querySelectorAll('.track-row').forEach(row=>{const id=row.querySelector('[data-action="play-track"]')?.dataset.id;row.classList.toggle('is-active',id===state.current)})}try{navigator.mediaSession.playbackState=playing?'playing':'paused'}catch{}}
audio.addEventListener('playing',()=>onPlayState(true));
audio.addEventListener('pause',()=>onPlayState(false));
audio.addEventListener('ended',()=>nextTrack(true));
audio.addEventListener('loadedmetadata',updateProgress);
audio.addEventListener('durationchange',updateProgress);
audio.addEventListener('timeupdate',()=>{
  updateProgress();
  if(state.playing){
    const now=Date.now();
    if(now-lastListenMark>=1000){
      state.listenSeconds+=Math.floor((now-lastListenMark)/1000);
      lastListenMark=now;
      if(state.listenSeconds%15===0)saveSettings();
    }
  } else lastListenMark=Date.now();
  if(state.sleepUntil&&Date.now()>state.sleepUntil){audio.pause();state.sleepUntil=0;toast('Sleep timer finished')}
});
audio.addEventListener('error',()=>{if(audio.src)toast('Unsupported audio format or playback error','error')});

function updateMediaSession(){if(!('mediaSession'in navigator)||!state.current)return;const t=track(state.current);if(!t)return;try{navigator.mediaSession.metadata=new MediaMetadata({title:t.title,artist:t.artist,album:'chimpanzee PULSE'});navigator.mediaSession.setActionHandler('play',()=>togglePlay());navigator.mediaSession.setActionHandler('pause',()=>togglePlay());navigator.mediaSession.setActionHandler('nexttrack',()=>nextTrack());navigator.mediaSession.setActionHandler('previoustrack',()=>previousTrack());navigator.mediaSession.setActionHandler('seekto',event=>{if(Number.isFinite(event.seekTime))audio.currentTime=event.seekTime})}catch(e){console.warn('MediaSession unsupported',e)}}
/* Canvas spectrum, driven by actual audio data once AudioContext is active. */
function bindHero(){const canvas=$('#hero-canvas');if(canvas&&canvas!==window.__pulseCanvas){window.__pulseCanvas=canvas;canvas.width=Math.round(canvas.clientWidth*devicePixelRatio);canvas.height=Math.round(canvas.clientHeight*devicePixelRatio)}}
function animate(){visualFrame=requestAnimationFrame(animate);if(++visualTicks%2!==0)return;const canvas=$('#hero-canvas');if(!canvas||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const dpr=Math.min(devicePixelRatio||1,2),w=Math.max(1,Math.round(canvas.clientWidth*dpr)),h=Math.max(1,Math.round(canvas.clientHeight*dpr));if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h}const ctx=canvas.getContext('2d');if(!ctx)return;ctx.clearRect(0,0,w,h);const cx=w*.52,cy=h*.5,base=Math.min(w,h)*.37,bars=66;let bins=null;if(analyser&&state.playing){analyser.getByteFrequencyData(frequencyData);bins=frequencyData}const time=performance.now()*.001;ctx.save();ctx.translate(cx,cy);ctx.rotate(-Math.PI/2);for(let i=0;i<bars;i++){const idx=bins?Math.floor((i/bars)*(bins.length*.75)):0;const energy=bins?bins[idx]/255:.08+.04*Math.sin(time*1.2+i*.33);const amp=7+energy*(bins?55:10)*dpr;const theta=i/bars*2*Math.PI;const hue=13+i/bars*35;ctx.strokeStyle=`hsla(${hue},94%,72%,${.25+energy*.45})`;ctx.lineWidth=Math.max(1,1.6*dpr);ctx.beginPath();ctx.moveTo(Math.cos(theta)*base,Math.sin(theta)*base);ctx.lineTo(Math.cos(theta)*(base+amp),Math.sin(theta)*(base+amp));ctx.stroke()}ctx.restore()}
/* Room transport; only chat, queue, roles. No unauthorized audio redistribution. */
function roomEndpoint(){return state.roomServer.replace(/\/$/,'').replace(/^http:/,'ws:').replace(/^https:/,'wss:')+'/socket'}
function roomSend(type,data={}){if(state.connection?.readyState===WebSocket.OPEN){state.connection.send(JSON.stringify({type,...data}));return true}toast('Not connected to a station','error');return false}
function connectRoom(mode,opts){if(!state.roomServer){toast('Add your server address in Settings','error');route('settings');return}if(!/^wss?:\/\//.test(roomEndpoint())){toast('Use an HTTPS or WSS server address','error');return}try{state.connection?.close();const ws=new WebSocket(roomEndpoint());state.connection=ws;ws.onopen=()=>ws.send(JSON.stringify({type:mode,...opts}));ws.onmessage=evt=>{let msg;try{msg=JSON.parse(evt.data)}catch{return}if(msg.type==='error'){toast(msg.message,'error');return}if(msg.type==='joined'){state.room=msg.room;state.roomId=msg.id;state.role=msg.role;state.adminRequest=null;render();toast('You are connected')}if(msg.type==='state'){state.room=msg.room;render()}if(msg.type==='role'){state.role=msg.role;toast('Your station role is now '+msg.role);render()}if(msg.type==='admin-request'){state.adminRequest=msg;toast(`${msg.name} requested admin`);render()}if(msg.type==='ended'){state.room=null;state.roomId=null;state.role=null;render();toast('The station ended')}};ws.onerror=()=>toast('Station connection failed','error');ws.onclose=()=>{if(state.connection!==ws)return;state.connection=null;if(state.room){state.room=null;state.roomId=null;state.role=null;render();toast('Station disconnected','error')}}}catch(e){console.error(e);toast('Check the server address','error')}}
function roomLeave(){const ws=state.connection;state.connection=null;state.room=null;state.role=null;state.roomId=null;ws?.close();render();toast('Left the station')}
/* Modals */
function showModal(title,body,footer=''){const root=$('#modal-root');root.innerHTML=`<div class="modal-backdrop" data-action="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-label="${escapeHTML(title)}"><div class="modal-top"><h2>${escapeHTML(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="Close">${icon('close')}</button></div>${body}${footer?`<div class="modal-footer">${footer}</div>`:''}</div></div>`;root.querySelector('.field')?.focus()}
function closeModal(){$('#modal-root').innerHTML=''}
function modalPlaylist(){showModal('New playlist',`<p>Some songs deserve their own universe. What will you call yours?</p><form id="new-playlist-form"><div class="form-group"><label for="new-playlist-name">PLAYLIST NAME</label><input class="field" id="new-playlist-name" maxlength="45" placeholder="After hours, Sunday drive…" required></div><button class="primary-btn" type="submit">${icon('plus')} Create playlist</button></form>`)}
function modalTrack(id){const t=track(id);if(!t)return;showModal('Track options',`<p><strong style="color:var(--fg)">${escapeHTML(t.title)}</strong><br>${escapeHTML(t.artist)}</p><div class="pill-menu"><button data-action="queue-add" data-id="${id}">${icon('queue')} Queue next</button><button data-action="playlist-add-modal" data-id="${id}">${icon('playlists')} Add to playlist</button><button data-action="edit-track-modal" data-id="${id}">${icon('edit')} Edit details</button><button data-action="delete-track-modal" data-id="${id}">${icon('trash')} Delete</button></div>`)}
function modalAddPlaylist(id){if(!Object.keys(state.playlists).length){closeModal();modalPlaylist();toast('Create a playlist first');return}showModal('Add to playlist',`<p>Choose the playlist for this song.</p>${Object.keys(state.playlists).map(name=>`<button class="modal-playlist-option" data-action="playlist-add-track" data-id="${id}" data-name="${escapeHTML(name)}">${icon('playlists')} ${escapeHTML(name)}</button>`).join('')}`)}
function modalEditTrack(id){const t=track(id);if(!t)return;showModal('Edit track details',`<form id="edit-track-form" data-id="${id}"><div class="form-group"><label for="edit-title">SONG TITLE</label><input class="field" id="edit-title" maxlength="120" value="${escapeHTML(t.title)}" required></div><div class="form-group"><label for="edit-artist">ARTIST</label><input class="field" id="edit-artist" maxlength="120" value="${escapeHTML(t.artist)}" required></div><button class="primary-btn" type="submit">${icon('check')} Save changes</button></form>`)}
function modalSleep(){showModal('Sleep timer',`<p>Let the music find its resting place.</p><div class="pill-menu">${[5,15,30,45,60,90].map(n=>`<button data-action="sleep-start" data-minutes="${n}">${n} min</button>`).join('')}<button data-action="sleep-cancel">Off</button></div>`)}
function confirmModal(title,text,action,label){showModal(title,`<p>${escapeHTML(text)}</p>`,`<button class="secondary-btn" data-action="close-modal">Cancel</button><button class="secondary-btn danger" data-action="${action}">${icon('trash')} ${escapeHTML(label)}</button>`)}
/* Delegated UI events */
document.addEventListener('click',async e=>{const button=e.target.closest('[data-action]');if(!button)return;const action=button.dataset.action,id=button.dataset.id,page=button.dataset.page,name=button.dataset.name;
 if(action==='modal-backdrop'){if(e.target===button)closeModal();return}
 if(action==='navigate'){route(page);return}
 if(action==='navigate-library'){route('library');return}
 if(action==='close-modal'){closeModal();return}
 if(action==='import'){$('#file-input').click();return}
 if(action==='toggle-theme'){state.theme=state.theme==='light'?'dark':'light';saveSettings();render();return}
 if(action==='search-focus'){route('library');setTimeout(()=>$('#library-search')?.focus(),30);return}
 if(action==='filter'){state.filter=button.dataset.filter;render();return}
 if(action==='clear-filter'){state.query='';state.filter='all';render();return}
 if(action==='play-track'){await playTrack(id);return}
 if(action==='toggle-play'||action==='resume'){await togglePlay();return}
 if(action==='next'){await nextTrack();return}
 if(action==='previous'){await previousTrack();return}
 if(action==='shuffle'){state.shuffle=!state.shuffle;saveSettings();renderPlayer();if(state.page==='settings')render();toast(state.shuffle?'Shuffle on':'Shuffle off');return}
 if(action==='repeat'){state.repeat=({off:'all',all:'one',one:'off'})[state.repeat]||'all';saveSettings();renderPlayer();if(state.page==='settings')render();toast('Repeat '+state.repeat);return}
 if(action==='favorite'){const t=track(id);if(t)await patchTrack(id,{favorite:!t.favorite});return}
 if(action==='track-menu'){modalTrack(id);return}
 if(action==='edit-track-modal'){modalEditTrack(id);return}
 if(action==='delete-track-modal'){confirmModal('Delete this track?','This removes the audio file from the app, but not from the original folder on your device.','delete-track-confirm','Delete track');$('#modal-root [data-action="delete-track-confirm"]').dataset.id=id;return}
 if(action==='delete-track-confirm'){closeModal();await deleteTrack(id);return}
 if(action==='queue-add'){if(!state.queue.includes(id)){const i=getQueueIndex();state.queue.splice(Math.max(0,i+1),0,id)}closeModal();saveSettings();toast('Added to queue');if(state.page==='queue')render();return}
 if(action==='queue-play'){if(state.queue.length)await loadTrack(state.queue[0],true);return}
 if(action==='queue-remove'){state.queue=state.queue.filter(x=>x!==id);saveSettings();render();return}
 if(action==='queue-up'||action==='queue-down'){const index=state.queue.indexOf(id),next=index+(action==='queue-up'?-1:1);if(next<0||next>=state.queue.length)return;[state.queue[index],state.queue[next]]=[state.queue[next],state.queue[index]];saveSettings();render();return}
 if(action==='queue-clear'){confirmModal('Clear the queue?','This removes all tracks from the play queue, but your library stays untouched.','queue-clear-confirm','Clear queue');return}
 if(action==='queue-clear-confirm'){state.queue=[];saveSettings();closeModal();render();toast('Queue cleared');return}
 if(action==='playlist-new'){modalPlaylist();return}
 if(action==='playlist-open'){state.playlist=name;render();return}
 if(action==='playlist-back'){state.playlist=null;render();return}
 if(action==='playlist-play'){const ids=(state.playlists[state.playlist]||[]).filter(track);if(ids.length){state.queue=[...ids];saveSettings();await loadTrack(ids[0],true)}return}
 if(action==='playlist-delete'){confirmModal('Delete playlist?',`Remove ${state.playlist} from your playlists? Your saved audio files won't be deleted.`,'playlist-delete-confirm','Delete playlist');return}
 if(action==='playlist-delete-confirm'){delete state.playlists[state.playlist];state.playlist=null;saveSettings();closeModal();render();toast('Playlist deleted');return}
 if(action==='playlist-remove'){state.playlists[state.playlist]=state.playlists[state.playlist].filter(x=>x!==id);saveSettings();render();return}
 if(action==='playlist-add-modal'){modalAddPlaylist(id);return}
 if(action==='playlist-add-track'){if(!state.playlists[name])return;if(!state.playlists[name].includes(id))state.playlists[name].push(id);saveSettings();closeModal();toast('Added to '+name);return}
 if(action==='mute'){state.volume=state.volume===0?.85:0;audio.volume=state.volume;saveSettings();renderPlayer();return}
 if(action==='sleep-modal'){modalSleep();return}
 if(action==='sleep-start'){state.sleepUntil=Date.now()+Number(button.dataset.minutes)*60000;closeModal();toast('Sleep timer set');render();return}
 if(action==='sleep-cancel'){state.sleepUntil=0;closeModal();toast('Sleep timer off');render();return}
 if(action==='save-server'){const raw=$('#server-url').value.trim();if(raw&&!/^https:\/\//.test(raw)&&!/^wss:\/\//.test(raw)&&!/^http:\/\/localhost(?::\d+)?\/?$/.test(raw)){toast('Use HTTPS or WSS (localhost may use HTTP)','error');return}state.roomServer=raw;state.profile=$('#profile-name').value.trim().slice(0,30)||'Listener';saveSettings();toast('Station settings saved');return}
 if(action==='storage-persist'){if(!navigator.storage?.persist){toast('Storage protection unavailable');return}const accepted=await navigator.storage.persist();toast(accepted?'Device storage protection enabled':'Your browser controls storage retention');return}
 if(action==='export-data'){const data={format:'chimpanzee-pulse-playlists-v1',savedAt:new Date().toISOString(),playlists:Object.entries(state.playlists).map(([title,ids])=>({title,tracks:ids.map(id=>track(id)).filter(Boolean).map(t=>({title:t.title,artist:t.artist}))}))};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='chimpanzee-playlists.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('Playlist metadata exported (audio not included)');return}
 if(action==='delete-all'){confirmModal('Erase your library?','This permanently removes audio, queues and playlists from this app on this device. Original music files elsewhere are unaffected.','delete-all-confirm','Erase everything');return}
 if(action==='delete-all-confirm'){audio.pause();++state.playerToken;audio.removeAttribute('src');audio.load();if(objectURL)URL.revokeObjectURL(objectURL);objectURL=null;await dbClear();state.tracks.clear();state.queue=[];state.playlists={};state.current=null;state.playing=false;state.listenSeconds=0;state.playlist=null;saveSettings();closeModal();route('home');toast('Local library cleared');return}
 if(action==='room-create'){const name=$('#host-name')?.value.trim().slice(0,30)||'Host';connectRoom('create',{name});return}
 if(action==='room-join'){const pin=$('#join-pin')?.value.trim();if(!/^\d{4}$/.test(pin)){toast('Enter a four-digit PIN','error');return}const name=$('#join-name')?.value.trim().slice(0,30)||'Listener';connectRoom('join',{pin,name});return}
 if(action==='room-leave'){roomLeave();return}
 if(action==='room-chat'){const field=$('#chat-message');if(field?.value.trim()){roomSend('chat',{message:field.value.trim()});field.value=''}return}
 if(action==='copy-pin'){navigator.clipboard?.writeText(state.room?.pin||'').then(()=>toast('PIN copied')).catch(()=>toast('Copy this PIN: '+state.room?.pin));return}
 if(action==='request-admin'){roomSend('request-admin');toast('Request sent to host');return}
 if(action==='room-admin'){roomSend('admin',{id,grant:button.dataset.grant==='true'});return}
 if(action==='grant-request'){if(state.adminRequest){roomSend('admin',{id:state.adminRequest.id,grant:true});state.adminRequest=null;render()}return}
 if(action==='room-track-add'){const url=$('#room-link')?.value.trim()||'',title=$('#room-link-title')?.value.trim()||'Shared link';try{const u=new URL(url);if(u.protocol!=='https:'||!['youtube.com','www.youtube.com','m.youtube.com','youtu.be','drive.google.com'].includes(u.hostname))throw Error('Unsupported');roomSend('queue-add',{url,title});}catch{toast('Use a valid YouTube or Google Drive HTTPS link','error')}return}
 if(action==='room-link-open'){try{const u=new URL(button.dataset.url);if(['youtube.com','www.youtube.com','m.youtube.com','youtu.be','drive.google.com'].includes(u.hostname)&&u.protocol==='https:')window.open(u.href,'_blank','noopener,noreferrer')}catch{}return}
 if(action==='room-track-remove'){roomSend('queue-remove',{id});return}
});
document.addEventListener('submit',async e=>{if(e.target.id==='new-playlist-form'){e.preventDefault();const name=$('#new-playlist-name').value.trim();if(!name)return;if(state.playlists[name]){toast('A playlist with that name already exists','error');return}state.playlists[name]=[];state.playlist=name;saveSettings();closeModal();render();toast('Playlist created')}if(e.target.id==='edit-track-form'){e.preventDefault();const id=e.target.dataset.id,title=$('#edit-title').value.trim(),artist=$('#edit-artist').value.trim();if(!title||!artist)return;closeModal();await patchTrack(id,{title,artist});toast('Track details updated')}});
document.addEventListener('input',e=>{if(e.target.id==='seek'){const max=Number(e.target.max)||0,v=Number(e.target.value);e.target.style.setProperty('--fill',(max?v/max*100:0)+'%');if(Number.isFinite(v)&&audio.src)audio.currentTime=v;updateProgress()}if(e.target.id==='volume'){state.volume=Number(e.target.value);audio.volume=state.volume;e.target.style.setProperty('--fill',state.volume*100+'%');saveSettings()}if(e.target.id==='library-search'){state.query=e.target.value;const start=e.target.selectionStart,end=e.target.selectionEnd;const focus=e.target===document.activeElement;const top=window.scrollY;$('#screen').innerHTML=renderLibrary();const field=$('#library-search');if(focus){field.focus();try{field.setSelectionRange(start,end)}catch{}window.scrollTo(0,top)}}});
document.addEventListener('change',e=>{if(e.target.id==='library-sort'){state.sort=e.target.value;render()}if(e.target.id==='playback-rate'){state.rate=Number(e.target.value);audio.playbackRate=state.rate;saveSettings();toast(`Playing at ${state.rate}× speed`)}});
$('#file-input').addEventListener('change',async e=>{await importFiles(e.target.files);e.target.value=''});
document.addEventListener('dragover',e=>{if(e.dataTransfer?.types.includes('Files')){e.preventDefault();$('#drop-zone')?.classList.add('drag-over')}});
document.addEventListener('dragleave',e=>{if(!e.relatedTarget)$('#drop-zone')?.classList.remove('drag-over')});
document.addEventListener('drop',e=>{if(e.dataTransfer?.files.length){e.preventDefault();$('#drop-zone')?.classList.remove('drag-over');importFiles(e.dataTransfer.files)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();return}if(e.target.closest('input,textarea,select,[contenteditable]')){if(e.key==='Enter'&&e.target.id==='chat-message'){e.preventDefault();document.querySelector('[data-action="room-chat"]')?.click()}return}if(e.key==='/'){e.preventDefault();route('library');$('#library-search')?.focus()}if(e.code==='Space'){e.preventDefault();togglePlay()}if(e.code==='ArrowRight'&&audio.src)audio.currentTime=Math.min(audio.duration||0,audio.currentTime+5);if(e.code==='ArrowLeft'&&audio.src)audio.currentTime=Math.max(0,audio.currentTime-5)});
window.addEventListener('resize',()=>{const m=$('.mobile-transport');if(m)m.style.display=window.innerWidth<=800?'flex':'none'});
window.addEventListener('beforeunload',saveSettings);
async function boot(){setBodyTheme();try{state.db=await openDB();const records=await dbAll();for(const rec of records)state.tracks.set(rec.id,publicMeta(rec));state.queue=state.queue.filter(id=>state.tracks.has(id));for(const title in state.playlists)state.playlists[title]=state.playlists[title].filter(id=>state.tracks.has(id));if(state.current&&!state.tracks.has(state.current))state.current=null;saveSettings();render();if(state.current)await loadTrack(state.current,false)}catch(e){console.error('Database initialization failed',e);toast('Local storage unavailable. Audio import may not work.','error');render()}requestAnimationFrame(animate);if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('sw.js').catch(e=>console.warn('Offline shell caching unavailable',e))}
boot();